//! TLS of the MQTT listener: a broker with a certificate generated by the test, MQTT clients over TLS that trust
//! it (rustls with the `ring` provider, MQTT packets from `common`), plain TCP clients against the TLS listener.

mod common;

use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;

use common::{connect, packet, publish, subscribe, WAIT};
use dt_server::broker::{Broker, BrokerLimits, BrokerOptions, BrokerTls};
use rustls::pki_types::{CertificateDer, ServerName};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpStream;
use tokio::time::timeout;
use tokio_rustls::client::TlsStream;
use tokio_rustls::TlsConnector;

/// Certificate files of one test and the certificate as clients see it.
struct Certs {
    dir: PathBuf,
    der: CertificateDer<'static>,
}

impl Drop for Certs {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

impl Certs {
    fn new(name: &str) -> Certs {
        let rcgen::CertifiedKey { cert, key_pair } =
            rcgen::generate_simple_self_signed(vec!["localhost".to_owned()]).unwrap();
        let dir = std::env::temp_dir().join(format!("dt-tls-it-{name}-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("fullchain.pem"), cert.pem()).unwrap();
        std::fs::write(dir.join("privkey.pem"), key_pair.serialize_pem()).unwrap();
        Certs {
            dir,
            der: cert.der().clone(),
        }
    }

    fn tls(&self) -> BrokerTls {
        BrokerTls::load(
            &self.dir.join("fullchain.pem"),
            &self.dir.join("privkey.pem"),
        )
        .unwrap()
    }

    /// A client configuration that trusts exactly this certificate.
    fn connector(&self) -> TlsConnector {
        let mut roots = rustls::RootCertStore::empty();
        roots.add(self.der.clone()).unwrap();
        let config = rustls::ClientConfig::builder_with_provider(Arc::new(
            rustls::crypto::ring::default_provider(),
        ))
        .with_safe_default_protocol_versions()
        .unwrap()
        .with_root_certificates(roots)
        .with_no_client_auth();
        TlsConnector::from(Arc::new(config))
    }
}

async fn start(certs: &Certs, limits: BrokerLimits) -> Broker {
    Broker::start_with(
        0,
        limits,
        BrokerOptions {
            tls: Some(certs.tls()),
            ..BrokerOptions::default()
        },
    )
    .await
    .expect("broker with TLS starts")
}

fn addr(broker: &Broker) -> String {
    format!("127.0.0.1:{}", broker.port())
}

/// An MQTT client over TLS that talks in raw packets.
struct TlsClient {
    stream: TlsStream<TcpStream>,
}

impl TlsClient {
    async fn open(connector: &TlsConnector, addr: &str) -> std::io::Result<TlsClient> {
        TlsClient::over(connector, TcpStream::connect(addr).await?).await
    }

    async fn over(connector: &TlsConnector, tcp: TcpStream) -> std::io::Result<TlsClient> {
        let name = ServerName::try_from("localhost").unwrap();
        let stream = timeout(WAIT, connector.connect(name, tcp))
            .await
            .expect("handshake in time")?;
        Ok(TlsClient { stream })
    }

    async fn connected(connector: &TlsConnector, addr: &str, client_id: &str) -> TlsClient {
        let mut client = TlsClient::open(connector, addr)
            .await
            .expect("TLS handshake");
        client.send(&connect(client_id)).await;
        let (first, body) = client.read_packet().await.expect("CONNACK");
        assert_eq!(first, 0x20, "expected CONNACK");
        assert_eq!(body, [0x00, 0x00], "accepted, no session present");
        client
    }

    /// Reads until the connection ends; `true` if it ended (close_notify, reset or EOF) within `WAIT`.
    async fn closed(&mut self) -> bool {
        let mut sink = [0u8; 256];
        timeout(WAIT, async {
            while let Ok(n) = self.stream.read(&mut sink).await {
                if n == 0 {
                    break;
                }
            }
        })
        .await
        .is_ok()
    }

    async fn send(&mut self, bytes: &[u8]) {
        self.stream.write_all(bytes).await.unwrap();
        self.stream.flush().await.unwrap();
    }

    /// One packet (first byte and body); `None` if the connection ended.
    async fn read_packet(&mut self) -> Option<(u8, Vec<u8>)> {
        timeout(WAIT, async {
            let first = self.stream.read_u8().await.ok()?;
            let mut len = 0usize;
            let mut shift = 0;
            loop {
                let b = self.stream.read_u8().await.ok()?;
                len |= usize::from(b & 0x7F) << shift;
                if b & 0x80 == 0 {
                    break;
                }
                shift += 7;
            }
            let mut body = vec![0u8; len];
            self.stream.read_exact(&mut body).await.ok()?;
            Some((first, body))
        })
        .await
        .expect("timed out waiting for a packet")
    }
}

/// Waits until the broker counts `expected` open connections.
async fn wait_for_connections(broker: &Broker, expected: usize) {
    let deadline = tokio::time::Instant::now() + WAIT;
    while broker.connection_count() != expected {
        assert!(
            tokio::time::Instant::now() < deadline,
            "connection count is {}, expected {expected}",
            broker.connection_count()
        );
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
}

/// Reads from a plain TCP stream until the peer closes it; returns what came.
async fn read_until_eof(stream: &mut TcpStream, limit: Duration) -> Vec<u8> {
    let mut data = Vec::new();
    match timeout(limit, stream.read_to_end(&mut data)).await {
        Ok(_) => data, // closed (an error such as a reset counts as closed as well)
        Err(_) => panic!("the connection was not closed within {limit:?}"),
    }
}

#[tokio::test]
async fn publish_and_subscribe_over_tls() {
    let certs = Certs::new("roundtrip");
    let broker = start(&certs, BrokerLimits::default()).await;
    let connector = certs.connector();
    let addr = addr(&broker);

    let mut subscriber = TlsClient::connected(&connector, &addr, "tls-sub").await;
    subscriber.send(&subscribe(1, &["tls/#"])).await;
    let (first, body) = subscriber.read_packet().await.expect("SUBACK");
    assert_eq!(first, 0x90);
    assert_eq!(body, [0, 1, 0]);

    let mut publisher = TlsClient::connected(&connector, &addr, "tls-pub").await;
    publisher
        .send(&publish("tls/topic", b"hello over tls"))
        .await;

    let (first, body) = subscriber.read_packet().await.expect("PUBLISH");
    assert_eq!(first, 0x30);
    let mut expected = 9u16.to_be_bytes().to_vec();
    expected.extend_from_slice(b"tls/topic");
    expected.extend_from_slice(b"hello over tls");
    assert_eq!(body, expected);

    // ping over TLS as well
    publisher.send(&packet(0xC0, &[])).await;
    assert_eq!(publisher.read_packet().await.unwrap().0, 0xD0);

    assert_eq!(broker.connection_count(), 2);
    drop((subscriber, publisher));
    broker.shutdown().await;
}

#[tokio::test]
async fn the_whole_chain_is_sent() {
    // a "fullchain.pem" with two certificates: the client receives both
    let leaf = rcgen::generate_simple_self_signed(vec!["localhost".to_owned()]).unwrap();
    let other = rcgen::generate_simple_self_signed(vec!["ca.example".to_owned()]).unwrap();
    let dir = std::env::temp_dir().join(format!("dt-tls-it-chain-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(
        dir.join("fullchain.pem"),
        format!("{}{}", leaf.cert.pem(), other.cert.pem()),
    )
    .unwrap();
    std::fs::write(dir.join("privkey.pem"), leaf.key_pair.serialize_pem()).unwrap();
    let certs = Certs {
        dir,
        der: leaf.cert.der().clone(),
    };
    let broker = start(&certs, BrokerLimits::default()).await;
    let client = TlsClient::open(&certs.connector(), &addr(&broker))
        .await
        .expect("handshake");
    let (_, conn) = client.stream.get_ref();
    let chain = conn.peer_certificates().expect("certificates");
    assert_eq!(
        chain.len(),
        2,
        "leaf and the second certificate of the file"
    );
    assert_eq!(chain[0], leaf.cert.der().clone());
    assert_eq!(chain[1], other.cert.der().clone());
}

#[tokio::test]
async fn client_that_does_not_trust_the_certificate_is_refused() {
    let certs = Certs::new("untrusted");
    let broker = start(&certs, BrokerLimits::default()).await;
    let stranger = Certs::new("stranger");
    let result = TlsClient::open(&stranger.connector(), &addr(&broker)).await;
    assert!(
        result.is_err(),
        "the certificate is not trusted by this client"
    );
    wait_for_connections(&broker, 0).await;
}

#[tokio::test]
async fn plain_client_is_rejected_and_the_broker_keeps_working() {
    let certs = Certs::new("plain");
    let limits = BrokerLimits {
        max_connections_per_ip: 2,
        ..BrokerLimits::default()
    };
    let broker = start(&certs, limits).await;
    let addr = addr(&broker);

    // an MQTT CONNECT in plain text is not a TLS ClientHello: the connection is closed, and nothing that looks like
    // a CONNACK comes back
    for _ in 0..4 {
        let mut plain = TcpStream::connect(&addr).await.unwrap();
        plain.write_all(&connect("plain")).await.unwrap();
        let answer = read_until_eof(&mut plain, WAIT).await;
        assert_ne!(answer.first(), Some(&0x20), "no CONNACK in plain text");
    }
    // every failed handshake released its slot (the limit per IP is 2)
    wait_for_connections(&broker, 0).await;

    let mut client = TlsClient::connected(&certs.connector(), &addr, "after-plain").await;
    client.send(&packet(0xC0, &[])).await;
    assert_eq!(client.read_packet().await.unwrap().0, 0xD0);
    broker.shutdown().await;
}

#[tokio::test]
async fn silent_connection_is_dropped_after_the_connect_timeout() {
    let certs = Certs::new("silent");
    let limits = BrokerLimits {
        connect_timeout_s: 1,
        max_connections_per_ip: 2,
        ..BrokerLimits::default()
    };
    let broker = start(&certs, limits).await;
    let addr = addr(&broker);

    // two TCP connections that never start the handshake fill the limit per IP ...
    let mut silent1 = TcpStream::connect(&addr).await.unwrap();
    let mut silent2 = TcpStream::connect(&addr).await.unwrap();
    wait_for_connections(&broker, 2).await;
    // ... the accept loop is not blocked by them: a third one is accepted and rejected by the limit at once
    let mut third = TcpStream::connect(&addr).await.unwrap();
    assert!(read_until_eof(&mut third, Duration::from_millis(900))
        .await
        .is_empty());

    // after the timeout both are closed by the broker without a single byte, and the slots are free again
    let started = tokio::time::Instant::now();
    assert!(read_until_eof(&mut silent1, Duration::from_secs(4))
        .await
        .is_empty());
    assert!(read_until_eof(&mut silent2, Duration::from_secs(4))
        .await
        .is_empty());
    assert!(started.elapsed() < Duration::from_secs(4));
    wait_for_connections(&broker, 0).await;

    TlsClient::connected(&certs.connector(), &addr, "after-silent").await;
    broker.shutdown().await;
}

#[tokio::test]
async fn tls_client_that_never_sends_connect_is_dropped() {
    let certs = Certs::new("no-connect");
    let limits = BrokerLimits {
        connect_timeout_s: 1,
        ..BrokerLimits::default()
    };
    let broker = start(&certs, limits).await;
    let mut client = TlsClient::open(&certs.connector(), &addr(&broker))
        .await
        .expect("handshake");
    // the handshake is done, CONNECT does not come: closed after the same timeout
    assert!(client.read_packet().await.is_none());
    wait_for_connections(&broker, 0).await;
}

#[tokio::test]
async fn broker_without_tls_stays_plain() {
    // the default options: a TLS client cannot talk to it, a plain one can
    let certs = Certs::new("plain-broker");
    let broker = Broker::start(0, BrokerLimits::default()).await.unwrap();
    let result = TlsClient::open(&certs.connector(), &addr(&broker)).await;
    assert!(result.is_err(), "a plain broker does not speak TLS");
    let mut raw = common::Raw::connected(&common::addr(&broker), "plain-ok").await;
    raw.send(&packet(0xC0, &[])).await;
    assert_eq!(raw.read_packet().await.unwrap().0, 0xD0);
    broker.shutdown().await;
}

#[tokio::test]
async fn refused_connack_arrives_over_tls_before_the_close() {
    let certs = Certs::new("refused");
    let broker = start(&certs, BrokerLimits::default()).await;
    let mut client = TlsClient::open(&certs.connector(), &addr(&broker))
        .await
        .expect("handshake");
    // empty client id without clean session: "identifier rejected" (0x02)
    client.send(&common::connect_raw(0, 30, "", &[])).await;
    let (first, body) = client.read_packet().await.expect("CONNACK");
    assert_eq!(first, 0x20);
    assert_eq!(body, [0x00, 0x02]);
    assert!(
        client.closed().await,
        "the connection is closed after the refusal"
    );
    wait_for_connections(&broker, 0).await;
}

#[tokio::test]
async fn large_burst_arrives_complete_and_in_order_at_a_slow_tls_reader() {
    // The subscriber reads nothing while the broker queues far more than the socket buffers hold, then reads it
    // all: the burst has to arrive complete and in order, the last message without the client sending anything.
    // Note: on Windows loopback this does not reliably reproduce the stuck tail without the flush (the kernel
    // buffers decide); the deterministic test of the writer is `writer_flushes_what_it_wrote_before_it_waits` in
    // `broker::session::tests`. This one checks that a large burst to a slow TLS client arrives complete.
    const MESSAGES: usize = 160;
    const PAYLOAD: usize = 64 * 1024;
    // The last message is the largest: it is written while the socket is nearly full, so that the end of it
    // stays in the buffer of the TLS stream if nothing flushes it.
    const LAST_PAYLOAD: usize = 200 * 1024;
    let certs = Certs::new("flush");
    let limits = BrokerLimits {
        max_pending_send_bytes: 64 * 1024 * 1024,
        ..BrokerLimits::default()
    };
    let broker = start(&certs, limits).await;
    let connector = certs.connector();
    let addr = addr(&broker);

    // a small receive buffer on the subscriber, so that the socket of the broker fills up quickly
    let socket = socket2::Socket::new(socket2::Domain::IPV4, socket2::Type::STREAM, None).unwrap();
    socket.set_recv_buffer_size(4096).unwrap();
    socket
        .connect(&addr.parse::<std::net::SocketAddr>().unwrap().into())
        .unwrap();
    socket.set_nonblocking(true).unwrap();
    let tcp = TcpStream::from_std(socket.into()).unwrap();
    let mut subscriber = TlsClient::over(&connector, tcp).await.expect("handshake");
    subscriber.send(&connect("slow-sub")).await;
    assert_eq!(subscriber.read_packet().await.unwrap().0, 0x20);
    subscriber.send(&subscribe(1, &["burst"])).await;
    assert_eq!(subscriber.read_packet().await.unwrap().0, 0x90);

    let mut publisher = TlsClient::connected(&connector, &addr, "burst-pub").await;
    for i in 0..MESSAGES {
        let mut payload = vec![
            0u8;
            if i + 1 == MESSAGES {
                LAST_PAYLOAD
            } else {
                PAYLOAD
            }
        ];
        payload[..8].copy_from_slice(&(i as u64).to_be_bytes());
        publisher.send(&publish("burst", &payload)).await;
    }
    // let the broker queue and write until the socket is full
    tokio::time::sleep(Duration::from_millis(1500)).await;

    for i in 0..MESSAGES {
        let (first, body) = subscriber
            .read_packet()
            .await
            .expect("PUBLISH of the burst");
        assert_eq!(first, 0x30);
        let at = 2 + "burst".len();
        assert_eq!(
            body[at..at + 8],
            (i as u64).to_be_bytes(),
            "message {i} in order"
        );
        let expected = if i + 1 == MESSAGES {
            LAST_PAYLOAD
        } else {
            PAYLOAD
        };
        assert_eq!(body.len(), at + expected);
    }
    broker.shutdown().await;
}
